INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-gen-0006','exam-sg','リスク管理','standard','single_choice','情報資産のリスク評価で、一般に組み合わせて評価する要素として最も適切なものはどれか。','[{"id":"a","text":"脅威、脆弱性、影響度"},{"id":"b","text":"社員数、売上高、会社規模"},{"id":"c","text":"CPU使用率、画面解像度、通信速度"},{"id":"d","text":"契約日、請求日、支払日"}]','"a"','正解は A。リスク評価では、脅威が脆弱性を利用して発生する可能性と、発生した場合の影響を考慮します。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0007','exam-sg','アクセス制御','standard','single_choice','退職した従業員のアカウントについて、最も適切な対応はどれか。','[{"id":"a","text":"問い合わせに備えて永久に有効にする"},{"id":"b","text":"退職日以降、規程に従って速やかに無効化する"},{"id":"c","text":"パスワードだけを短く変更する"},{"id":"d","text":"共有アカウントに変更して残す"}]','"b"','正解は B。退職や異動に伴い、不要になった権限を速やかに削除・無効化することが重要です。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0008','exam-sg','インシデント対応','standard','single_choice','マルウェア感染が疑われるPCを発見したとき、最も適切な初動はどれか。','[{"id":"a","text":"証拠を残さず、すぐに全ファイルを削除する"},{"id":"b","text":"組織の手順に従いネットワークから隔離し、担当窓口へ報告する"},{"id":"c","text":"同じUSBメモリを別のPCでも試す"},{"id":"d","text":"原因を確認する前にSNSへ投稿する"}]','"b"','正解は B。被害拡大を防ぐため隔離し、手順に従って報告します。ログや証拠を不用意に消さないことも重要です。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0009','exam-sg','暗号化','standard','single_choice','公開鍵暗号方式で、送信者が受信者だけに読めるデータを送る場合、通常どの鍵で暗号化するか。','[{"id":"a","text":"送信者の秘密鍵"},{"id":"b","text":"受信者の公開鍵"},{"id":"c","text":"受信者の秘密鍵"},{"id":"d","text":"誰でも知っている共通パスワード"}]','"b"','正解は B。機密性を確保する場合は受信者の公開鍵で暗号化し、対応する受信者の秘密鍵で復号します。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0010','exam-sg','電子署名','standard','single_choice','電子署名が主に確認する性質の組合せとして最も適切なものはどれか。','[{"id":"a","text":"機密性と通信速度"},{"id":"b","text":"送信元の真正性と改ざんの検知"},{"id":"c","text":"可用性とバックアップ容量"},{"id":"d","text":"匿名性とデータ圧縮率"}]','"b"','正解は B。電子署名は署名者の確認と、署名対象データが改ざんされていないことの検証に使われます。署名だけで内容の機密性が得られるわけではありません。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0011','exam-sg','バックアップ','standard','single_choice','ランサムウェア被害に備えるバックアップ運用として、最も適切なものはどれか。','[{"id":"a","text":"本番PCに接続した同じディスクだけに保存する"},{"id":"b","text":"バックアップを定期取得し、分離保管と復元テストを行う"},{"id":"c","text":"バックアップの存在だけ確認し復元は試さない"},{"id":"d","text":"すべてのバックアップを同じ管理者パスワードで公開する"}]','"b"','正解は B。攻撃から分離したバックアップと定期的な復元テストにより、復旧可能性を高めます。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0012','exam-sg','個人情報保護','standard','single_choice','顧客情報を外部委託先へ提供する際、最も適切な対応はどれか。','[{"id":"a","text":"目的や取扱条件を確認せず全データを渡す"},{"id":"b","text":"必要性、契約、アクセス制限、安全管理措置を確認する"},{"id":"c","text":"委託先なら誰でも自由に再提供できる"},{"id":"d","text":"提供後は管理責任が一切なくなる"}]','"b"','正解は B。委託の必要性と範囲を限定し、契約・安全管理措置・監督方法を確認します。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0013','exam-sg','標的型攻撃','standard','single_choice','取引先を装ったメールに不審な添付ファイルがある場合、最も適切な対応はどれか。','[{"id":"a","text":"急ぎと書かれていればすぐ開く"},{"id":"b","text":"別経路で送信元を確認し、組織の報告手順に従う"},{"id":"c","text":"同僚全員に転送して開いてもらう"},{"id":"d","text":"マクロを有効にして内容を確認する"}]','"b"','正解は B。表示された差出人だけを信用せず、別経路で確認し、不審メールを報告します。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0014','exam-sg','脆弱性管理','standard','single_choice','重要な脆弱性が公表されたとき、組織の対応として最も適切なものはどれか。','[{"id":"a","text":"影響を調べず、すべての更新を無期限に延期する"},{"id":"b","text":"対象資産と影響を確認し、優先順位を付けて修正・緩和する"},{"id":"c","text":"公表された情報をすべて無視する"},{"id":"d","text":"修正後の確認を行わない"}]','"b"','正解は B。資産の把握、影響評価、優先順位付け、修正と検証を一連の管理として行います。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0015','exam-sg','ネットワーク','standard','single_choice','社外から社内システムへ安全に接続する方法として、一般に適切なものはどれか。','[{"id":"a","text":"認証なしで管理画面をインターネットに公開する"},{"id":"b","text":"多要素認証などを組み合わせた承認済みVPN等を利用する"},{"id":"c","text":"全社員で管理者アカウントを共有する"},{"id":"d","text":"暗号化を無効にする"}]','"b"','正解は B。承認された安全な接続経路と強固な認証を使い、権限を必要最小限にします。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0016','exam-sg','ログ管理','standard','single_choice','システムログを保管する目的として最も適切なものはどれか。','[{"id":"a","text":"障害や不正アクセスの調査、監査に役立てる"},{"id":"b","text":"利用者のパスワードを平文で記録する"},{"id":"c","text":"ログがあればバックアップは不要になる"},{"id":"d","text":"保存したログは誰でも変更できるようにする"}]','"a"','正解は A。ログは監視、障害分析、インシデント調査、監査証跡に利用します。改ざん防止やアクセス制限も必要です。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0017','exam-sg','委託先管理','standard','single_choice','クラウドサービスを利用する前に確認すべき事項として最も適切なものはどれか。','[{"id":"a","text":"サービス名の響きだけ"},{"id":"b","text":"データの保管場所、アクセス管理、障害対応、契約条件"},{"id":"c","text":"広告の表示回数だけ"},{"id":"d","text":"担当者の個人的な評判だけ"}]','"b"','正解は B。データ保護、権限管理、可用性、インシデント対応、契約と責任分界を確認します。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0018','exam-sg','事業継続','standard','single_choice','事業継続計画（BCP）の主な目的はどれか。','[{"id":"a","text":"災害や重大障害時にも重要業務を継続・早期復旧する"},{"id":"b","text":"すべてのリスクを完全になくす"},{"id":"c","text":"平常時の売上だけを予測する"},{"id":"d","text":"情報資産の一覧を作らないようにする"}]','"a"','正解は A。BCPは重大な中断が発生した場合に重要業務を継続または許容時間内に復旧するための計画です。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0019','exam-sg','内部不正','standard','single_choice','内部不正のリスクを低減する対策として最も適切なものはどれか。','[{"id":"a","text":"一人に申請・承認・実行のすべてを任せる"},{"id":"b","text":"職務分掌、最小権限、操作ログの確認を組み合わせる"},{"id":"c","text":"共有IDを増やす"},{"id":"d","text":"退職者の権限を残す"}]','"b"','正解は B。権限を分離し、必要最小限のアクセスと監査可能な記録を組み合わせます。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0020','exam-sg','認証','standard','single_choice','パスワードの使い回しを避ける理由として最も適切なものはどれか。','[{"id":"a","text":"一つのサービスから漏えいすると、他サービスへの不正ログインにも悪用されるため"},{"id":"b","text":"パスワードを長くすると必ず漏えいするため"},{"id":"c","text":"多要素認証が利用できなくなるため"},{"id":"d","text":"ログの保存容量が増えるため"}]','"a"','正解は A。漏えいした認証情報を別サービスで試すパスワードリスト攻撃の被害を抑えるため、使い回しを避けます。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0021','exam-sg','情報分類','standard','single_choice','情報資産の分類ルールを定める主な目的はどれか。','[{"id":"a","text":"すべての情報を同じ方法で公開する"},{"id":"b","text":"重要度や機密性に応じた取扱い・保護策を適用する"},{"id":"c","text":"情報の所有者を不明にする"},{"id":"d","text":"情報の保存期限を必ず無期限にする"}]','"b"','正解は B。分類に応じてアクセス、保存、送信、廃棄などのルールを適用します。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0022','exam-sg','廃棄・消去','standard','single_choice','機密情報を含む記憶媒体を廃棄するとき、最も適切な方法はどれか。','[{"id":"a","text":"通常の削除操作だけで必ず安全とみなす"},{"id":"b","text":"情報の機密度と媒体に応じた消去・破壊を行い、必要に応じ記録する"},{"id":"c","text":"廃棄前に内容を公開する"},{"id":"d","text":"誰でも持ち帰れる場所に置く"}]','"b"','正解は B。媒体の特性と情報の機密度に応じて、復元困難な消去や物理破壊を行います。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0023','exam-sg','セキュリティ教育','standard','single_choice','従業員向け情報セキュリティ教育の効果を高める方法として最も適切なものはどれか。','[{"id":"a","text":"入社時に一度だけ説明し、その後は見直さない"},{"id":"b","text":"役割に応じて定期的に教育し、理解度や訓練結果を確認する"},{"id":"c","text":"技術部門だけを対象にする"},{"id":"d","text":"実際の手順を知らせない"}]','"b"','正解は B。定期的で役割に応じた教育と、訓練や理解度確認を組み合わせます。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0024','exam-sg','変更管理','standard','single_choice','本番システムの変更管理として最も適切なものはどれか。','[{"id":"a","text":"承認やテストを省略し、直接変更する"},{"id":"b","text":"影響評価、承認、テスト、実施記録、必要時の切戻し計画を用意する"},{"id":"c","text":"変更内容を記録しない"},{"id":"d","text":"障害が起きても元に戻せないようにする"}]','"b"','正解は B。変更の影響を評価し、承認・検証・記録・切戻しを含む手順で安全に実施します。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0025','exam-sg','リスク対応','standard','single_choice','リスク対応のうち、保険加入などによって損失の負担を第三者へ移す考え方はどれか。','[{"id":"a","text":"リスク回避"},{"id":"b","text":"リスク低減"},{"id":"c","text":"リスク移転"},{"id":"d","text":"リスク受容"}]','"c"','正解は C。保険や契約などでリスクの一部を第三者へ移すことをリスク移転といいます。リスク自体が必ず消えるわけではありません。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0026','exam-sg','セキュリティ方針','standard','single_choice','情報セキュリティポリシーを組織に定着させるうえで最も適切なものはどれか。','[{"id":"a","text":"経営層の関与、役割の明確化、周知と定期的な見直しを行う"},{"id":"b","text":"文書を作成した後は誰にも知らせない"},{"id":"c","text":"責任者を決めない"},{"id":"d","text":"業務やリスクが変わっても改訂しない"}]','"a"','正解は A。方針には経営層の支援、責任分担、周知、運用確認と継続的な見直しが必要です。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0027','exam-sg','Webセキュリティ','standard','single_choice','WebアプリケーションのSQLインジェクション対策として最も適切なものはどれか。','[{"id":"a","text":"入力値を文字列連結してSQL文を作る"},{"id":"b","text":"プレースホルダーを用いたパラメータ化クエリを利用する"},{"id":"c","text":"エラーメッセージにDB認証情報を含める"},{"id":"d","text":"入力検証をすべて無効にする"}]','"b"','正解は B。パラメータ化クエリにより、入力値がSQL命令として解釈されるリスクを大きく低減できます。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0028','exam-sg','可用性','standard','single_choice','サービスの可用性を高める対策として最も適切なものはどれか。','[{"id":"a","text":"単一障害点を把握し、冗長化と復旧手順を整備する"},{"id":"b","text":"監視を停止する"},{"id":"c","text":"障害時の連絡先を削除する"},{"id":"d","text":"バックアップを一切取らない"}]','"a"','正解は A。冗長化、監視、復旧手順、定期的な訓練によってサービス停止の影響を抑えます。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0029','exam-sg','認証情報管理','standard','single_choice','多要素認証の説明として最も適切なものはどれか。','[{"id":"a","text":"同じパスワードを二回入力する"},{"id":"b","text":"知識・所持・生体など異なる種類の要素を組み合わせる"},{"id":"c","text":"ユーザー名と表示名を入力する"},{"id":"d","text":"秘密の質問を複数設定すれば必ず多要素となる"}]','"b"','正解は B。異なる認証要素の種類を組み合わせます。同じ種類の要素を複数使うだけでは多要素とは限りません。','generated','知学原创 SG 专项练习题库 v2','ja'),
('sg-gen-0030','exam-sg','監査','standard','single_choice','情報セキュリティ監査の主な目的として最も適切なものはどれか。','[{"id":"a","text":"統制や運用が基準・方針に沿っているかを独立した立場から評価する"},{"id":"b","text":"監査対象者のパスワードを集める"},{"id":"c","text":"すべての業務を監査人が代わりに実行する"},{"id":"d","text":"問題を発見しても報告しない"}]','"a"','正解は A。監査では、基準や方針に対する適合性、統制の有効性などを証拠に基づいて評価します。','generated','知学原创 SG 专项练习题库 v2','ja');
